// Event frame, little-endian: u16 cap | f32 value.
// Must stay byte-for-byte in sync with messaging/MeoEventFrame.java and the
// firmware's Meo3_Messaging.cpp (meo-3-open-service/docs/mqtt_messaging.md).
module.exports = (function() {
    "use strict";

    var FRAME_SIZE = 6;

    return {
        // Always f32: an event carries a READ reading or an EVENT occurrence,
        // never a WRITE result. null when the length is wrong — nothing in a
        // malformed frame can be trusted.
        parse: function(payload) {
            if (!Buffer.isBuffer(payload) || payload.length !== FRAME_SIZE) { return null; }
            return {
                cap: payload.readUInt16LE(0),
                value: payload.readFloatLE(2)
            };
        }
    };
}());
